//! What a full chunk's slot image costs to make (`svet-render`'s `SlotImage::of`, ADR-0056),
//! the work a stream worker takes on beside the bake's face masks: a solid chunk, a surface
//! chunk of the streamed cave and a canopy chunk of the forest, each generated by the
//! fly-through's own source over its default material table. It lives with the fly-through
//! because the sources do. Before the timings it prints each chunk's coordinate, its `Full`
//! bricks and the image's held bytes.
//!
//! The chunks are picked from a box of chunks around each source's spawn by a fixed rule, so
//! a run reads the same chunks: the solid chunk is the first of the cave's box with no `Full`
//! brick and no air brick; the cave's surface chunk is its box's chunk with the most `Full`
//! bricks; the canopy chunk is the forest box's chunk wholly above the ground under its centre
//! with the most `Full` bricks.

use std::hint::black_box;

use criterion::{Criterion, criterion_group, criterion_main};
use flythrough::cave::{CaveSource, UNBOUNDED_SPAWN};
use flythrough::outdoor::{OutdoorSource, Spawn};
use flythrough::trees::{ForestSource, LEAF_FILL, TreeDensity};
use svet_world::{AIR, Brick, CHUNK_EDGE, Chunk, ChunkCoord, MaterialTable, WorldSource};

/// The fly-through's default table for `source` (`--source <source>`).
fn table(source: &str) -> MaterialTable {
    let argv = ["--source", source].map(str::to_owned);
    let args = flythrough::cli::parse_args_from(argv).expect("the arguments parse");
    let (file, _) = flythrough::materials::load(None).expect("the default materials load");
    flythrough::materials::selection(&args)
        .compose(&file)
        .expect("the default selection composes")
}

fn full_bricks(ch: &Chunk) -> usize {
    ch.bricks().iter().filter(|b| b.is_full()).count()
}

/// The chunks of the box of half-edge `r` around `centre`, each generated by `source`, in
/// z, y, x order.
fn around(source: &dyn WorldSource, centre: ChunkCoord, r: i32) -> Vec<(ChunkCoord, Chunk)> {
    let mut out = Vec::new();
    for z in -r..=r {
        for y in -r..=r {
            for x in -r..=r {
                let c = ChunkCoord([centre.0[0] + x, centre.0[1] + y, centre.0[2] + z]);
                let mut ch = Chunk::default();
                source.chunk(c, &mut ch);
                out.push((c, ch));
            }
        }
    }
    out
}

fn chunk_of(v: [i32; 3]) -> ChunkCoord {
    ChunkCoord(v.map(|v| v.div_euclid(CHUNK_EDGE)))
}

/// The three chunks of the module docs, named.
fn chunks() -> Vec<(&'static str, ChunkCoord, Chunk, MaterialTable)> {
    // The fly-through's default `--seed`.
    let seed = 1;
    let cave = CaveSource::unbounded(seed);
    let cave_box = around(&cave, chunk_of(UNBOUNDED_SPAWN.0), 2);
    let solid = cave_box
        .iter()
        .find(|(_, ch)| {
            ch.bricks()
                .iter()
                .all(|b| matches!(b, Brick::Uniform(m) if *m != AIR))
        })
        .or_else(|| {
            // No chunk of the box is solid throughout: the one with the fewest `Full` bricks
            // and no air brick.
            cave_box
                .iter()
                .filter(|(_, ch)| !ch.bricks().contains(&Brick::Uniform(AIR)))
                .min_by_key(|(_, ch)| full_bricks(ch))
        })
        .expect("a chunk of the cave's box holds no air brick");
    let surface = cave_box
        .iter()
        .max_by_key(|(c, ch)| (full_bricks(ch), std::cmp::Reverse(*c)))
        .expect("the box is not empty");

    let hills = OutdoorSource::new(seed);
    let (eye, _) = hills.spawn(Spawn::Forest);
    let forest = ForestSource::new(hills, TreeDensity::default(), LEAF_FILL);
    let canopy = around(&forest, chunk_of(eye.0), 2)
        .into_iter()
        .filter(|(c, _)| {
            let mid = c.0.map(|v| v * CHUNK_EDGE + CHUNK_EDGE / 2);
            c.0[2] * CHUNK_EDGE > hills.height(mid[0], mid[1])
        })
        .max_by_key(|(c, ch)| (full_bricks(ch), std::cmp::Reverse(*c)))
        .expect("a chunk of the forest's box lies above the ground");
    let cave_table = table("cave");
    vec![
        ("solid", solid.0, solid.1.clone(), cave_table.clone()),
        ("cave surface", surface.0, surface.1.clone(), cave_table),
        ("forest canopy", canopy.0, canopy.1, table("outdoor")),
    ]
}

fn slot_image(c: &mut Criterion) {
    let mut group = c.benchmark_group("slot_image");
    for (name, coord, chunk, table) in chunks() {
        let make = svet_render::internals::slot_image_maker(&table);
        println!(
            "slot image: {name} chunk {:?}: {} full bricks, {} bytes held",
            coord.0,
            full_bricks(&chunk),
            make(coord, &chunk)
        );
        group.bench_function(name, |b| {
            b.iter(|| make(black_box(coord), black_box(&chunk)))
        });
    }
    group.finish();
}

criterion_group!(benches, slot_image);
criterion_main!(benches);
